/* MedicCare.module.css */

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #eaeaea;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #000000;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #FFFFFF;
  --vt-accent-on-deep: #1a5bbf;
  --vt-line: #eaeaea;
  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  font-size: 18px;
  line-height: 1.5;
  letter-spacing: 0.5px;
}

/* Navigation */
.nav {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.1);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 1rem 0;
}

.navIn {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.navGroup {
  display: flex;
  gap: 2rem;
}

.navLink {
  color: var(--vt-ink-soft);
  font-weight: 600;
  text-decoration: none;
  padding: 0.5rem 0;
  transition: color 0.3s;
}

.navLink:hover,
.navLink:focus-visible {
  color: var(--vt-ink);
}

.logo {
  text-decoration: none;
  color: var(--vt-accent);
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  margin: 0 2rem;
}

.brand {
  display: block;
  font-size: 1.25rem;
  line-height: 1.2;
}

.brand strong {
  color: var(--vt-ink-soft);
  font-size: 0.75rem;
  display: block;
}

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  margin-top: 74px;
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.heroTrack::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  min-width: 100%;
  scroll-snap-align: start;
}

.heroSlide img {
  width: 100%;
  height: 580px;
  object-fit: cover;
  display: block;
}

.heroCard {
  position: absolute;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-sizing: border-box;
  z-index: 2;
}

.heroTitle {
  font-size: 3rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin: 0 0 1rem;
}

.heroText {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  margin-bottom: 2rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
}

.customLink:hover {
  background: var(--vt-line);
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  font-size: 1.125rem;
}

/* About */
.about {
  padding: 5rem 0;
  background: var(--vt-surface);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

.sectionTitle {
  font-size: 2.25rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 2rem;
  color: var(--vt-ink);
}

.sectionText {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

/* Gallery */
.gallery {
  background: var(--vt-surface-2);
  padding: 0;
}

.galleryGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
}

.galleryItem {
  margin: 0;
}

.galleryItem img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  display: block;
}

/* Timeline */
.timeline {
  padding: 5rem 0;
  background: var(--vt-surface);
}

.timelineGrid {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  padding: 2rem 0;
}

.timelineGrid::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  border-left: 1px solid var(--vt-line);
  transform: translateX(-50%);
}

.timelineNode {
  display: flex;
  position: relative;
  width: 50%;
  margin-bottom: 3rem;
  padding: 0 3rem 0 0;
  box-sizing: border-box;
}

.timelineNode.even {
  left: 0;
  text-align: right;
  padding-right: 4rem;
}

.timelineNode.odd {
  left: 50%;
  text-align: left;
  padding-left: 4rem;
}

.timelineIcon {
  position: absolute;
  top: 0;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  font-size: 2rem;
  color: var(--vt-accent);
}

.timelineNode.even .timelineIcon {
  right: -40px;
}

.timelineNode.odd .timelineIcon {
  left: -40px;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.1);
  border-radius: 0.5rem;
  padding: 1rem;
  width: 100%;
}

.timelineHeading {
  position: relative;
  background: var(--vt-ink);
  color: var(--vt-surface);
  padding: 0.75rem 1.5rem;
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
  border-radius: 0.25rem 0.25rem 0 0;
}

.timelineText {
  padding: 1rem 1.5rem;
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 1rem;
}

.timelineNode.even .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.odd .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.footerGrid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 2rem;
}

.footerCol {
  padding: 0 1rem;
}

.footerHeading {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
}

.footerCol p,
.footerCol a {
  color: var(--vt-ink-soft);
  font-size: 1rem;
}

.socialLinks {
  display: flex;
  gap: 1rem;
  list-style: none;
  padding: 0;
  margin: 0;
}

.socialLinks a {
  color: var(--vt-ink-soft);
  font-size: 1.5rem;
  transition: color 0.3s;
}

.socialLinks a:hover {
  color: var(--vt-accent);
}

.copyright {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid var(--vt-line);
}

.copyright p {
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 991px) {
  .heroTitle {
    font-size: 2.5rem;
  }
  .sectionTitle {
    font-size: 2rem;
  }
  .timelineHeading {
    font-size: 1.25rem;
  }
  .heroSlide img {
    height: 450px;
  }
  .heroCard {
    padding: 1rem 2rem;
  }
}

@media (max-width: 767px) {
  .hero {
    margin-top: 60px;
  }
  .navIn {
    flex-direction: column;
    gap: 1rem;
  }
  .navGroup {
    width: 100%;
    justify-content: center;
  }
  .logo {
    order: -1;
    margin: 1rem 0;
  }
  .heroCard {
    position: relative;
    width: 100%;
    bottom: auto;
    right: auto;
    padding: 1.5rem;
    box-shadow: none;
  }
  .heroTrack {
    display: block;
  }
  .heroSlide {
    min-width: auto;
  }
  .heroSlide img {
    height: auto;
    max-height: 400px;
  }
  .galleryGrid {
    grid-template-columns: 1fr;
  }
  .footerGrid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }
  .timelineGrid::before {
    left: 30px;
  }
  .timelineNode {
    width: 100%;
    left: 0 !important;
    padding: 0 0 0 80px;
    text-align: left;
    margin-bottom: 2rem;
  }
  .timelineNode.even,
  .timelineNode.odd {
    left: 0;
    padding-right: 0;
    padding-left: 80px;
  }
  .timelineNode.even .timelineIcon,
  .timelineNode.odd .timelineIcon {
    left: 0;
    right: auto;
    width: 60px;
    height: 60px;
    font-size: 1.5rem;
    top: 0;
  }
  .timelineNode.even .timelineHeading::after,
  .timelineNode.odd .timelineHeading::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-ink);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }
}

@media (max-width: 575px) {
  .timelineGrid::before {
    left: 45px;
  }
  .timelineNode {
    padding-left: 70px;
  }
  .timelineNode.even,
  .timelineNode.odd {
    padding-left: 70px;
  }
  .timelineNode.even .timelineIcon,
  .timelineNode.odd .timelineIcon {
    width: 50px;
    height: 50px;
    font-size: 1.25rem;
    left: 10px;
    top: 0;
  }
  .heroTitle {
    font-size: 2rem;
  }
  .customLink {
    font-size: 0.75rem;
    line-height: 30px;
    padding: 0 20px;
  }
  .contactPhone {
    font-size: 0.9rem;
  }
}
